(7429592, 1174215, 34192, '<td valign="top">I love this. I love the way you put it together. Its an uncollage. It makes so much sense. Now I''m kicking myself. 10</td>', 'I love this. I love the way you put it together. Its an uncollage. It makes so much sense. Now I''m kicking myself. 10', '2016-01-18 09:10:05.000000', NULL, 1),
(7429593, 1174121, 34192, '<td valign="top">A beautiful abstract. 8</td>', 'A beautiful abstract. 8', '2016-01-18 09:13:51.000000', NULL, 1),
(7429594, 1174122, 34192, '<td valign="top">I like this. I would like it even more had the background been gray and the snow white. It makes a pretty cool graphic abstract. 6</td>', 'I like this. I would like it even more had the background been gray and the snow white. It makes a pretty cool graphic abstract. 6', '2016-01-18 09:15:30.000000', NULL, 1),
(7429619, 1174097, 114225, '<td valign="top">Wonderful use of the aspect ratio.</td>', 'Wonderful use of the aspect ratio.', '2016-01-18 10:36:59.000000', NULL, 1),
(7429620, 1173995, 114225, '<td valign="top">I really enjoy this.</td>', 'I really enjoy this.', '2016-01-18 10:37:23.000000', NULL, 1),
(7429671, 1173748, 181814, '<td valign="top">This is very nice I like the focus the exposure and I really can''t tell where your stitching is which is good. Well done.</td>', 'This is very nice I like the focus the exposure and I really can''t tell where your stitching is which is good. Well done.', '2016-01-18 12:47:34.000000', NULL, 1),
(7429673, 1173995, 181814, '<td valign="top">Very interesting panorama, looks good in black and white, the only problem I have with it is on the right upper corner which in my opinion if it were cropped a bit closer maybe it would look a bit better, that is just a nitpick from me and overall this is a great looking photograph.</td>', 'Very interesting panorama, looks good in black and white, the only problem I have with it is on the right upper corner which in my opinion if it were cropped a bit closer maybe it would look a bit better, that is just a nitpick from me and overall this is a great looking photograph.', '2016-01-18 12:49:18.000000', NULL, 1),
(7429674, 1174121, 181814, '<td valign="top">This is very interesting and extremely well stitched together. I know it''s frost but it actually looks like something growing in a science lab :-) this is one of my favorites in this contest and I hope it does well.</td>', 'This is very interesting and extremely well stitched together. I know it''s frost but it actually looks like something growing in a science lab :-) this is one of my favorites in this contest and I hope it does well.', '2016-01-18 12:52:08.000000', NULL, 1),
(7429675, 1174116, 181814, '<td valign="top">This is very well done, I don''t know if these are real cars or model cars but they look good they are well focused the stitching is superbly done and I like the reflections of the cars. I really like this and it is one of my favorites for sure.</td>', 'This is very well done, I don''t know if these are real cars or model cars but they look good they are well focused the stitching is superbly done and I like the reflections of the cars. I really like this and it is one of my favorites for sure.', '2016-01-18 12:53:42.000000', NULL, 1),
(7429676, 1174197, 181814, '<td valign="top">I like the composition and the stitching looks okay but what I consider the main subject in the center seems to be out of focus.</td>', 'I like the composition and the stitching looks okay but what I consider the main subject in the center seems to be out of focus.', '2016-01-18 12:56:27.000000', NULL, 1),
(7429692, 1174177, 38496, '<td valign="top">my top pick for a ribbon.  Beautiful!</td>', 'my top pick for a ribbon.  Beautiful!', '2016-01-18 13:59:11.000000', NULL, 1),
