(7429699, 1173748, 114225, '<td valign="top">Hard shot to judge. It looks nice. Is it really a panoramic stitch?</td>', 'Hard shot to judge. It looks nice. Is it really a panoramic stitch?', '2016-01-18 14:14:28.000000', NULL, 1),
(7429701, 1174142, 114225, '<td valign="top">I think a little more width would have been really cool.</td>', 'I think a little more width would have been really cool.', '2016-01-18 14:14:52.000000', NULL, 1),
(7429702, 1174152, 114225, '<td valign="top">I find myself wishing for a bit more color pop. But still nice.</td>', 'I find myself wishing for a bit more color pop. But still nice.', '2016-01-18 14:15:20.000000', NULL, 1),
(7429703, 1174212, 114225, '<td valign="top">That''s a cool find. Doesn''t really appear all that close up.</td>', 'That''s a cool find. Doesn''t really appear all that close up.', '2016-01-18 14:15:41.000000', NULL, 1),
(7429704, 1174128, 114225, '<td valign="top">A very nice use of the wide aspect.</td>', 'A very nice use of the wide aspect.', '2016-01-18 14:15:56.000000', NULL, 1),
(7429705, 1174153, 114225, '<td valign="top">This has a lot going for it, with some flaws.<br/>Good detail and subject. Good aspect.<br/>But the highlights are so bright, they overpower the subject.</td>', 'This has a lot going for it, with some flaws.Good detail and subject. Good aspect.But the highlights are so bright, they overpower the subject.', '2016-01-18 14:16:32.000000', NULL, 1),
(7429706, 1174107, 114225, '<td valign="top">This seems to work nice.</td>', 'This seems to work nice.', '2016-01-18 14:16:43.000000', NULL, 1),
(7429707, 1174115, 114225, '<td valign="top">I have a bit of a hard time believing this is panoramic, but I do see what could be a stitching error.</td>', 'I have a bit of a hard time believing this is panoramic, but I do see what could be a stitching error.', '2016-01-18 14:17:31.000000', NULL, 1),
(7429708, 1174123, 114225, '<td valign="top">Meets the challenge, but basic toy shots are not my cup of tea.</td>', 'Meets the challenge, but basic toy shots are not my cup of tea.', '2016-01-18 14:17:50.000000', NULL, 1),
(7429709, 1174122, 114225, '<td valign="top">I find myself looking for more detail.</td>', 'I find myself looking for more detail.', '2016-01-18 14:18:03.000000', NULL, 1),
(7429710, 1174116, 114225, '<td valign="top">I''m guessing by the "license plates" that these are toys. Very deceptive.</td>', 'I''m guessing by the "license plates" that these are toys. Very deceptive.', '2016-01-18 14:18:24.000000', NULL, 1),
(7429711, 1174208, 114225, '<td valign="top">That''s kind of a cool idea. Seems more like a tight crop than a panoramic...</td>', 'That''s kind of a cool idea. Seems more like a tight crop than a panoramic...', '2016-01-18 14:18:51.000000', NULL, 1),
(7429712, 1174120, 114225, '<td valign="top">Something about hairy knuckles is unappealing to me.</td>', 'Something about hairy knuckles is unappealing to me.', '2016-01-18 14:19:08.000000', NULL, 1),
(7429713, 1173913, 114225, '<td valign="top">You could have very easily cropped the top portion, and cloned the bottom portion to fill in. Or take some more shots to stitch.</td>', 'You could have very easily cropped the top portion, and cloned the bottom portion to fill in. Or take some more shots to stitch.', '2016-01-18 14:20:01.000000', NULL, 1),
(7429714, 1174217, 114225, '<td valign="top">A lot of colors for something that seems dead. Feels like maybe the light could be a bit brighter.</td>', 'A lot of colors for something that seems dead. Feels like maybe the light could be a bit brighter.', '2016-01-18 14:24:03.000000', NULL, 1),
(7429717, 1174162, 114225, '<td valign="top">If I look at this longer, I appreciate it more. Not a good sign for voting here...</td>', 'If I look at this longer, I appreciate it more. Not a good sign for voting here...', '2016-01-18 14:28:11.000000', NULL, 1),
(7429718, 1174215, 114225, '<td valign="top">An interesting work of art. Not my style, but interesting.</td>', 'An interesting work of art. Not my style, but interesting.', '2016-01-18 14:28:37.000000', NULL, 1),
(7429719, 1174147, 114225, '<td valign="top">Really not sure what I''m looking at.</td>', 'Really not sure what I''m looking at.', '2016-01-18 14:28:54.000000', NULL, 1),
